        // Owner calls AdjustDifficulty(5) – only possible after buggy contract let the non-owner call
        vm.prank(address(this));
        c.AdjustDifficulty(5);
        // Assert that the difficulty matches the expected value based on whether the first call reverted
        assertTrue(c.currentDifficulty() == expectedDifficulty);
    }
}

