        // First user wagers and plays to make contract have some balance
        vm.deal(address(0x1), 1);
        vm.prank(address(0x1));
        c.wager{value: 1}();

        // Second user donates 1 wei
        vm.deal(address(0x2), 1);
        vm.prank(address(0x2));
        c.donate{value: 1}();

        // In reference: totalDonated becomes 1, whale receives 1 wei
        // In bug: totalDonated stays 0, whale receives nothing
        uint256 totalDonated = c.totalDonated();
        assertTrue(totalDonated == 1);
    }
}
